var CalendarPage_default = '/* Calendar and Timeline. Category colours come from the theme, not Calendarium. */\n.mw-cal {\n  --cat: var(--gray);\n  margin: 1rem 0 2rem;\n}\n\n.mw-cal [data-cat="festivals"] { --cat: var(--secondary); }\n.mw-cal [data-cat="star signs"] { --cat: #5b6b8f; }\n.mw-cal [data-cat="the party"] { --cat: var(--dark); }\n.mw-cal [data-cat="history"] { --cat: var(--tertiary); }\n.mw-cal [data-cat="eras"] { --cat: #8a6d4b; }\n.mw-cal [data-cat="wars"] { --cat: #8c3b2e; }\n:root[saved-theme="dark"] .mw-cal [data-cat="star signs"] { --cat: #9aa7c9; }\n:root[saved-theme="dark"] .mw-cal [data-cat="eras"] { --cat: #c9a47a; }\n:root[saved-theme="dark"] .mw-cal [data-cat="wars"] { --cat: #d0705f; }\n\n/* Header */\n.mw-cal-top {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  align-items: flex-end;\n  gap: 0.8rem;\n  margin-bottom: 0.8rem;\n}\n\n.mw-cal-title {\n  font-family: var(--headerFont);\n  font-size: 1.6rem;\n  color: var(--dark);\n  line-height: 1.2;\n}\n\n.mw-cal-year {\n  color: var(--gray);\n  font-size: 1.1rem;\n}\n\n.mw-cal-sub {\n  font-size: 0.85rem;\n  color: var(--gray);\n  margin-top: 0.2rem;\n}\n\n.mw-cal-nav {\n  display: flex;\n  gap: 0.4rem;\n}\n\n.mw-cal-nav button,\n.mw-tl-filter {\n  font-family: var(--bodyFont);\n  font-size: 0.85rem;\n  color: var(--darkgray);\n  background: transparent;\n  border: 1px solid var(--lightgray);\n  border-radius: 6px;\n  padding: 0.25rem 0.7rem;\n  cursor: pointer;\n}\n\n.mw-cal-nav button:hover,\n.mw-tl-filter:hover {\n  border-color: var(--secondary);\n}\n\n/* Ongoing strip */\n.mw-cal-ongoing {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.3rem 1rem;\n  border: 1px solid var(--lightgray);\n  border-left: 3px solid var(--secondary);\n  padding: 0.35rem 0.8rem;\n  margin-bottom: 0.8rem;\n  font-size: 0.88rem;\n}\n\n.mw-cal-ongoing-label {\n  font-variant: small-caps;\n  letter-spacing: 0.08em;\n  color: var(--gray);\n}\n\n/* Grid: 6-day week */\n.mw-cal-grid {\n  display: grid;\n  grid-template-columns: repeat(6, minmax(0, 1fr));\n  gap: 4px;\n}\n\n.mw-cal-wd {\n  font-variant: small-caps;\n  letter-spacing: 0.06em;\n  font-size: 0.85rem;\n  color: var(--gray);\n  text-align: center;\n  padding-bottom: 0.2rem;\n}\n\n.mw-cal-day {\n  position: relative;\n  min-height: 82px;\n  border: 1px solid var(--lightgray);\n  border-radius: 6px;\n  padding: 0.3rem 0.4rem;\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  background: color-mix(in srgb, var(--light) 70%, transparent);\n  outline: none;\n}\n\n.mw-cal-past .mw-cal-num {\n  color: var(--gray);\n}\n\n.mw-cal-num {\n  display: flex;\n  align-items: center;\n  gap: 0.35rem;\n  font-size: 0.85rem;\n  color: var(--darkgray);\n}\n\n.mw-cal-today {\n  border: 2px solid var(--secondary);\n}\n\n.mw-cal-today .mw-cal-num {\n  color: var(--dark);\n  font-weight: 600;\n}\n\n.mw-cal-today-tag {\n  font-size: 0.7rem;\n  font-weight: 400;\n  color: var(--secondary);\n  font-variant: small-caps;\n  letter-spacing: 0.06em;\n}\n\n.mw-cal-moon {\n  width: 9px;\n  height: 9px;\n  border-radius: 50%;\n  border: 1px solid var(--darkgray);\n}\n\n.mw-cal-moon.mw-new {\n  background: var(--darkgray);\n}\n\n.mw-cal-ev {\n  display: block;\n  font-size: 0.75rem;\n  line-height: 1.25;\n  padding: 1px 5px;\n  border-left: 3px solid var(--cat);\n  border-radius: 0 3px 3px 0;\n  background: color-mix(in srgb, var(--cat) 14%, transparent);\n  color: var(--darkgray) !important;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\na.mw-cal-ev,\n.mw-cal-ongoing a,\n.mw-cal-upcoming a {\n  background-color: color-mix(in srgb, var(--cat) 14%, transparent);\n  text-decoration: none;\n}\n\n.mw-cal-ongoing a,\n.mw-cal-upcoming a {\n  background: none;\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 3px;\n}\n\n/* Hover a day: all three date styles */\n.mw-cal-day:hover::after,\n.mw-cal-day:focus::after {\n  content: attr(data-tip);\n  position: absolute;\n  z-index: 5;\n  left: 50%;\n  bottom: calc(100% + 6px);\n  transform: translateX(-50%);\n  width: max-content;\n  max-width: 260px;\n  background: var(--light);\n  color: var(--dark);\n  border: 1px solid var(--dark);\n  border-radius: 4px;\n  padding: 0.3rem 0.55rem;\n  font-size: 0.78rem;\n  line-height: 1.35;\n  pointer-events: none;\n}\n\n/* Below the grid */\n.mw-cal-extra {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  gap: 1rem;\n  margin-top: 1rem;\n}\n\n.mw-cal-upcoming {\n  border: 1px solid var(--lightgray);\n  padding: 0.6rem 0.9rem;\n  min-width: 260px;\n}\n\n.mw-cal-box-title {\n  font-variant: small-caps;\n  letter-spacing: 0.12em;\n  color: var(--gray);\n  border-bottom: 1px solid var(--lightgray);\n  padding-bottom: 0.25rem;\n  margin-bottom: 0.4rem;\n}\n\n.mw-cal-upcoming ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.mw-cal-upcoming li {\n  display: flex;\n  justify-content: space-between;\n  gap: 1rem;\n  margin: 0.2rem 0;\n  font-size: 0.9rem;\n}\n\n.mw-cal-when {\n  color: var(--gray);\n  font-size: 0.85rem;\n}\n\n.mw-cal-key {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem 1rem;\n  align-self: flex-end;\n  font-size: 0.8rem;\n  color: var(--gray);\n}\n\n.mw-cal-key-item::before {\n  content: "";\n  display: inline-block;\n  width: 9px;\n  height: 9px;\n  margin-right: 0.35rem;\n  border-radius: 2px;\n  background: var(--cat);\n}\n\n@media (max-width: 700px) {\n  .mw-cal-day {\n    min-height: 54px;\n  }\n  .mw-cal-ev {\n    font-size: 0.65rem;\n  }\n}\n\n/* Timeline */\n.mw-tl-filters {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n  margin-bottom: 1rem;\n}\n\n.mw-tl-filter {\n  opacity: 0.55;\n}\n\n.mw-tl-filter.mw-on {\n  opacity: 1;\n  border-color: var(--cat);\n  box-shadow: inset 3px 0 0 var(--cat);\n}\n\n.mw-tl-row {\n  display: grid;\n  grid-template-columns: 5.5rem calc(var(--lanes, 1) * 10px) 14px minmax(0, 1fr);\n  column-gap: 0.6rem;\n  align-items: stretch;\n  min-height: 2rem;\n}\n\n.mw-tl-year {\n  text-align: right;\n  color: var(--gray);\n  font-size: 0.85rem;\n  padding-top: 0.35rem;\n}\n\n.mw-tl-bars {\n  display: grid;\n  grid-template-columns: repeat(var(--lanes, 1), 10px);\n}\n\n.mw-tl-seg {\n  grid-row: 1;\n  width: 6px;\n  background: var(--cat);\n  opacity: 0.75;\n}\n\n.mw-tl-seg-start {\n  border-radius: 3px 3px 0 0;\n  margin-top: 0.5rem;\n}\n\n.mw-tl-dot {\n  width: 10px;\n  height: 10px;\n  margin-top: 0.55rem;\n  border-radius: 50%;\n  background: var(--cat);\n}\n\n.mw-tl-dot-today {\n  background: transparent;\n  border: 2px solid var(--secondary);\n  box-sizing: border-box;\n}\n\n.mw-tl-what {\n  padding: 0.3rem 0;\n  font-size: 0.95rem;\n}\n\n.mw-tl-today .mw-tl-what,\n.mw-tl-today .mw-tl-year {\n  color: var(--secondary);\n}\n\n.mw-tl-span {\n  color: var(--gray);\n  font-size: 0.85rem;\n}\n\n.mw-tl-flag {\n  margin-left: 0.5rem;\n  font-size: 0.7rem;\n  padding: 0 0.4rem;\n  border-radius: 4px;\n  background: var(--lightgray);\n  color: var(--darkgray);\n}\n\n.mw-tl-private .mw-tl-what > :first-child {\n  font-style: italic;\n}\n\n.mw-tl-empty {\n  color: var(--gray);\n}\n';

